import Foundation
import OSLog

/// Offers to reopen an agent conversation in a restored pane (issue #145).
///
/// Deliberately **not** part of `TerminalAgentManager`, which owns failure classification and
/// diagnosis. Two reasons, and the first is a bug rather than a preference:
///
/// - `AgentBannerState` is failure-shaped — every case carries a `FailedCommand`, and
///   `failureAndDiagnosis` hands back a non-optional one that `AgentPrompt.investigateCommandLine`
///   destructures. A resume offer has no failed command.
/// - `TerminalAgentManager.banners` is **one slot per tab**, so an offer and a diagnosis would evict
///   each other. Concretely: a restored pane offers Resume, the user runs a command, it fails,
///   `commandFinished` overwrites the offer and it never comes back. Discovery is async, so the
///   reverse happens too — a late offer landing on top of a live `.loading` diagnosis.
///
/// The lifecycles differ as much as the states do. A diagnosis is triggered by an event in the pane
/// and costs an API call the user asked for; an offer is triggered by launch, costs a bounded
/// filesystem scan, and its action **spends the user's money**. That last point is why `consume` is
/// the only way to read an invocation out.
@MainActor
final class AgentResumeCoordinator: ObservableObject {
  private static let logger = Logger(
    subsystem: "com.developwithstyle.workroom", category: "agent-resume")

  /// Which agents a restored pane can be resumed into. Empty entries are never stored, so
  /// `offers[tab] != nil` means there is something to show.
  ///
  /// A `Set`, not an array: two `.claude` offers are meaningless, and array order would quietly
  /// acquire semantics ("the first one is the likely one") that this feature has no basis for —
  /// the app cannot know which agent a pane was running.
  @Published private(set) var offers: [TerminalTab.ID: Set<AgentBackend>] = [:]

  /// The directory each offer was matched against, so `consume` can refuse a pane that has since
  /// moved. Kept beside `offers` rather than inside it because the view has no use for it.
  private var offerCwds: [TerminalTab.ID: String] = [:]

  /// A cancellation flag the scan can read from its own queue.
  ///
  /// `DispatchWorkItem.isCancelled` would do, but reading it means capturing the work item inside its
  /// own closure, and the obvious workaround — hopping to the main actor to ask — is a
  /// `DispatchQueue.main.sync` from a utility queue on every directory entry: slow at best, a
  /// deadlock at worst. A lock-guarded flag is readable from anywhere and cheap enough to check in a
  /// loop.
  private final class CancellationFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var cancelled = false

    var isCancelled: Bool {
      lock.lock()
      defer { lock.unlock() }
      return cancelled
    }

    func cancel() {
      lock.lock()
      cancelled = true
      lock.unlock()
    }
  }

  private let index: AgentSessionIndex?
  private let queue = DispatchQueue(
    label: "com.developwithstyle.workroom.agent-resume", qos: .utility)
  private var discovery: CancellationFlag?
  /// Tabs whose offer must not be published, because the pane is gone or its offer was already
  /// spent.
  ///
  /// Only meaningful while a scan is in flight — its whole job is to stop `publish` re-offering a
  /// pane that was closed, typed into, or resumed while the scan ran. So it is cleared once the scan
  /// lands. An earlier version never pruned it, on the stated grounds that it was "bounded by the
  /// number of tabs a launch restores"; that was wrong, because `tabClosed` fires for EVERY tab
  /// closed in the process, restored or not, so it grew for the life of the app.
  private var abandoned: Set<TerminalTab.ID> = []

  /// `index: nil` disables discovery entirely — the fixture default, so the existing UI tests can
  /// never read the developer's real `~/.claude` (issue #46 drew the same line for the session file).
  init(index: AgentSessionIndex? = AgentSessionIndex()) {
    self.index = index
  }

  // MARK: Discovery

  /// Look for resumable conversations for the panes a restore just produced.
  ///
  /// **Fire and forget, and never awaited by the restore.** `restorePersistedSessionIfPending` ends
  /// with `finishSessionRestore()` in a `defer`, and issue #46's watchdog freezes session writes for
  /// the whole run if any window is still outstanding 15 seconds in. Blocking that on a filesystem
  /// scan would trade a nice-to-have button for the user's session persistence — the exact failure
  /// #46 built the watchdog to prevent.
  ///
  /// One scan for all panes, on a utility queue rather than a task per pane: the work is blocking
  /// file IO, which starves the cooperative pool (the bug behind the History pane's forever-spinner).
  func discover(_ restored: [TerminalSessions.RestoredTerminal], savedAt: Date) {
    guard let index, !restored.isEmpty else { return }
    discovery?.cancel()

    // Distinct directories only: a workroom with four restored panes is one directory to scan.
    let cwds = Array(Set(restored.map(\.cwd)))
    let flag = CancellationFlag()
    discovery = flag
    queue.async { [weak self] in
      let found = index.backends(
        forCwds: cwds, savedAt: savedAt, isCancelled: { flag.isCancelled })
      guard !flag.isCancelled else { return }
      DispatchQueue.main.async {
        MainActor.assumeIsolated { self?.publish(found, for: restored, flag: flag) }
      }
    }
  }

  private func publish(
    _ found: [String: Set<AgentBackend>], for restored: [TerminalSessions.RestoredTerminal],
    flag: CancellationFlag
  ) {
    // A scan superseded or cancelled while it was hopping back to the main actor publishes nothing.
    guard discovery === flag, !flag.isCancelled else { return }
    discovery = nil
    var offered = 0
    for pane in restored {
      // Dropped only when the pane itself is gone or its offer was spent — NOT when it stopped being
      // the selected tab. A background pane keeps its offer; that is the point of restoring several.
      guard !abandoned.contains(pane.tabID) else { continue }
      guard let backends = found[pane.cwd], !backends.isEmpty else { continue }
      offers[pane.tabID] = backends
      offerCwds[pane.tabID] = pane.cwd
      offered += 1
    }
    // The scan has landed, so the suppression list has done its job. Clearing it is what keeps it
    // from growing for the life of the process on every tab close.
    abandoned.removeAll()
    if offered > 0 {
      Self.logger.notice("resume offers published for \(offered, privacy: .public) restored panes")
    }
  }

  // MARK: Acting

  /// Take the offer and hand back the command to run — **atomically**.
  ///
  /// The offer is removed before the invocation is returned, so this can only succeed once. That is
  /// not tidiness: the action starts a billed agent session, and a double-click, a SwiftUI re-render
  /// firing the button's action twice, or two windows racing on the same pane would otherwise each
  /// start one. Returning nil on the second call is the button being spent, not an error.
  /// `liveCwd` is the pane's CURRENT directory, when it has reported one. The offer was matched
  /// against the directory the pane was restored into, and a shell hook (`direnv`, a `cd` in
  /// `.zshrc`, a project activator) can move it before the user ever touches the keyboard — none of
  /// which trips the pristine guard. Resuming there would open a picker listing a different
  /// project's conversations, which is precisely the confident-wrong-answer this feature refuses to
  /// give. A moved pane spends the offer and returns nothing.
  func consume(tab: TerminalTab.ID, backend: AgentBackend, liveCwd: String? = nil)
    -> AgentInvocation?
  {
    guard let backends = offers[tab], backends.contains(backend) else { return nil }
    offers[tab] = nil
    abandoned.insert(tab)
    if let liveCwd, let matched = offerCwds[tab],
      !AgentSessionIndex.pathsMatch(matched, liveCwd)
    {
      offerCwds[tab] = nil
      Self.logger.notice("resume offer dropped — the pane's directory changed since discovery")
      return nil
    }
    offerCwds[tab] = nil
    return AgentInvocationBuilder.resume(backend)
  }

  /// The pane received input, so it is no longer pristine (issue #145).
  ///
  /// Discovery is async: by the time an offer lands the user may already be halfway through typing a
  /// command, and appending `claude --resume` plus Return to a dirty input line runs something
  /// nobody asked for. Dropping the offer on the first keystroke is the fix. The alternative — a
  /// `Ctrl-U` kill-line before typing — is shell-dependent and destroys whatever they had typed, so
  /// it trades a wrong command for lost work.
  func paneReceivedInput(tab: TerminalTab.ID) {
    offers[tab] = nil
    offerCwds[tab] = nil
    // Only worth remembering while a scan could still publish for it; see `abandoned`.
    if discovery != nil { abandoned.insert(tab) }
  }

  /// The pane went away: drop its offer and make sure an in-flight scan cannot resurrect it.
  func tabClosed(_ tab: TerminalTab.ID) {
    offers[tab] = nil
    offerCwds[tab] = nil
    if discovery != nil { abandoned.insert(tab) }
  }

  /// Cancel any scan still running — the offers it would publish are for panes nobody is waiting on.
  func cancelDiscovery() {
    discovery?.cancel()
    discovery = nil
    // Nothing can publish now, so the suppression list has nothing left to suppress.
    abandoned.removeAll()
  }
}

import Foundation
import OSLog

/// Which agent CLIs have a resumable conversation for a given directory (issue #145).
///
/// libghostty exposes no child pid and no pty fd (`ghostty.h` carries only
/// `ghostty_surface_message_childexited_s`), so the app **cannot** know what was running in a pane.
/// The only answerable question is the weaker one: *does this directory have agent history from
/// around the time we quit?* That is a filesystem read of each agent's own session store.
///
/// **Matching is exact, never guessed.** Both stores record the working directory inside the session
/// file, so a candidate is confirmed by reading it:
///
/// - **Claude** — `~/.claude/projects/<slug>/<uuid>.jsonl`. Line 1 is a `{leafUuid, sessionId, type}`
///   summary with no `cwd`; the `user` / `assistant` / `attachment` records that follow each carry
///   one, so extraction scans forward to the first record that has it.
/// - **Codex** — `~/.codex/sessions/YYYY/MM/DD/rollout-*.jsonl`, whose first line is a
///   `session_meta` record with `payload.cwd`.
///
/// The slug is a **candidate-directory hint only** — it saves listing 58 project directories to find
/// the one that matters, and nothing rests on it being right. That distinction is load-bearing:
/// Claude's slug scheme replaces `.` as well as `/` (`/Users/x/.buzz` is stored as
/// `-Users-x--buzz`), and the treatment of other character classes is undocumented and not ours to
/// pin down. An earlier design keyed identity on a reconstructed slug; it would have silently shown
/// no button for any workroom path containing a dot, and had no way to tell that apart from "no
/// history here". When the hint misses, `enumerateClaudeProjects` finds it anyway.
///
/// Exact matching also **resolves** the `/a-b/c` vs `/a/b/c` slug collision rather than accepting it,
/// and removes any need to case-fold (wrong on a case-sensitive or external volume) or to resolve
/// symlinks before slugging (a session started through a symlink may be recorded under the textual
/// path, so resolving first looks in the wrong place).
///
/// Every read is best-effort and bounded. A missing, unreadable or enormous store yields no offers
/// and no error — the failure mode is a button that does not appear.
final class AgentSessionIndex {
  private static let logger = Logger(
    subsystem: "com.developwithstyle.workroom", category: "agent-resume")

  /// Hard bounds on the scan. Discovery runs on the launch path, and a Codex store accumulates one
  /// file per session forever — several thousand on a machine like this one — so "read them all"
  /// is not a bound. Every limit is enforced, and hitting one publishes a PARTIAL result rather
  /// than nothing: a missing button is the designed failure, an unbounded scan is not.
  struct Limits {
    /// Ceiling on files opened across the whole build. Directory entries are cheap; opens are not.
    var maxFiles = 2_000
    /// Ceiling per file. Only the head of a transcript is ever needed, and a session file grows
    /// without limit.
    var maxBytesPerFile = 256 * 1024
    /// How far into a Claude transcript to look for the first record carrying `cwd`. It is normally
    /// line 2; a long tool-result preamble could push it further, but not far.
    var maxLinesPerFile = 64
    /// Wall clock for the whole build.
    var deadline: TimeInterval = 3

    static let standard = Limits()
  }

  /// Where each agent keeps its transcripts. Rooted at a home directory so a UI test can seed a fake
  /// tree (`-WorkroomUITestAgentSessionRoot`) instead of reading the developer's real `~/.claude`.
  struct Roots {
    var claudeProjects: URL
    var codexSessions: URL

    init(home: URL) {
      claudeProjects = home.appendingPathComponent(".claude/projects", isDirectory: true)
      codexSessions = home.appendingPathComponent(".codex/sessions", isDirectory: true)
    }

    static var standard: Roots {
      Roots(home: URL(fileURLWithPath: NSHomeDirectory(), isDirectory: true))
    }
  }

  private let roots: Roots
  private let limits: Limits
  private let fileManager: FileManager
  /// Injected so tests drive the deadline without sleeping.
  private let now: () -> Date

  /// The Codex cwd set, computed once per launch and reused by every window.
  ///
  /// Walking the date tree is the expensive half of discovery and its answer does not vary by pane,
  /// so a second restoring window must not repeat it. Lock-guarded because `backends` runs on a
  /// utility queue and two windows can start within milliseconds of each other.
  private let memoLock = NSLock()
  private var codexCwdMemo: Set<String>?

  init(
    roots: Roots = .standard, limits: Limits = .standard, fileManager: FileManager = .default,
    now: @escaping () -> Date = Date.init
  ) {
    self.roots = roots
    self.limits = limits
    self.fileManager = fileManager
    self.now = now
  }

  /// The index this build should use, or **nil to disable discovery entirely**.
  ///
  /// Mirrors `SessionStore.forCurrentEnvironment`, and for the same reason: these stores belong to
  /// the developer, not to the app. A UI test gets a seeded fake `$HOME` only when it asks for one,
  /// and a unit test never gets a real store at all — otherwise `AgentSessionIndexTests` would pass
  /// or fail depending on which directories the developer had used an agent in that day.
  ///
  /// **One instance for the process.** `TerminalSessions` is per-`AppStore`, and `AppStore` is
  /// per-window, so a per-owner index would mean N restored windows each walking the Codex date
  /// tree from scratch — the duplicate work this was specified to avoid, quietly not avoided
  /// because the owner looked like a natural place to hang it. The instance is immutable and its
  /// only mutable state is the per-launch memo below, guarded by a lock, so sharing is safe.
  static let shared: AgentSessionIndex? = {
    if let root = UITestFixture.agentSessionRoot {
      return AgentSessionIndex(roots: Roots(home: URL(fileURLWithPath: root, isDirectory: true)))
    }
    guard !UITestFixture.isActive,
      ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] == nil
    else { return nil }
    return AgentSessionIndex()
  }()

  // MARK: Recency

  /// How far a session file's mtime may sit from the quit and still count (issue #145, D3).
  ///
  /// Deliberately not the ±5 minutes first proposed. A transcript's mtime is its last **message**,
  /// not the last moment the session was alive: leaving Claude idle at its prompt for forty minutes
  /// and then quitting — an ordinary way to end a day — puts the mtime far outside a five-minute
  /// window, and the feature silently does nothing on exactly the day it was wanted.
  ///
  /// Twelve hours is affordable only *because* matching is exact. With directory guessing a wider
  /// window multiplies genuine false positives; with a confirmed `cwd` a "false positive" means this
  /// exact directory really does have a resumable conversation, which is true information. Nothing
  /// auto-resumes either way — the click is the gate and the agent still shows its picker.
  static let recencyWindow: TimeInterval = 12 * 60 * 60

  /// Symmetric on purpose: a future-dated mtime is clock skew (or a restored backup), not evidence
  /// of absence.
  static func isRecent(_ modified: Date, savedAt: Date, window: TimeInterval = recencyWindow)
    -> Bool
  {
    abs(modified.timeIntervalSince(savedAt)) <= window
  }

  // MARK: Path comparison

  /// Whether a recorded `cwd` denotes the same directory as a pane's.
  ///
  /// Textual comparison first, because that is what the agent actually wrote. A symlink match is
  /// accepted as a secondary candidate — a session started through `/work/link` may be recorded
  /// under either the link or its target, and we cannot know which — but resolution is never applied
  /// *before* the textual check, or a session recorded under the link would stop matching.
  ///
  /// No `lowercased()`. The boot volume is case-insensitive by default, but a case-sensitive APFS
  /// volume or an external disk is not, and folding there would merge two genuinely different
  /// directories.
  static func pathsMatch(_ recorded: String, _ pane: String) -> Bool {
    let a = trimmed(recorded)
    let b = trimmed(pane)
    guard !a.isEmpty, !b.isEmpty else { return false }
    if a == b { return true }
    return resolved(a) == resolved(b)
  }

  /// Normalize only what is genuinely equivalent: a redundant trailing slash.
  ///
  /// Deliberately NOT `trimmingCharacters(in: .whitespacesAndNewlines)`. A space is a legal
  /// character in a POSIX filename, so trimming would make history recorded for `/work/project `
  /// match a pane at `/work/project` — two different directories, and the offer would open a picker
  /// for history the pane does not have. Only a trailing newline is stripped, since that is a
  /// transport artefact of reading the value out of a JSON line rather than part of the path.
  static func trimmed(_ path: String) -> String {
    var value = path
    while value.hasSuffix("\n") || value.hasSuffix("\r") { value.removeLast() }
    while value.count > 1, value.hasSuffix("/") { value.removeLast() }
    return value
  }

  static func resolved(_ path: String) -> String {
    trimmed(URL(fileURLWithPath: path).resolvingSymlinksInPath().path)
  }

  // MARK: Claude

  /// Claude's directory name for a working directory — a **hint**, not an identity. See the type
  /// comment: `/` and `.` both become `-`, other classes are undocumented, and every candidate this
  /// produces is confirmed against the `cwd` recorded inside the file before it counts.
  static func claudeSlugHint(for path: String) -> String {
    String(trimmed(path).map { $0 == "/" || $0 == "." ? "-" : $0 })
  }

  /// The working directory a Claude transcript records, or nil.
  ///
  /// Scans forward: line 1 is a summary record with no `cwd`, so stopping there would find nothing.
  static func claudeCwd(inLines lines: [String]) -> String? {
    for line in lines {
      guard let object = jsonObject(line), let cwd = object["cwd"] as? String, !cwd.isEmpty else {
        continue
      }
      return cwd
    }
    return nil
  }

  // MARK: Codex

  /// The working directory a Codex rollout records, from its `session_meta` first line.
  ///
  /// The type check is not decoration: a file whose first line is some other record kind is a shape
  /// we do not understand, and guessing at it would be how a future Codex format silently starts
  /// matching the wrong directory.
  static func codexCwd(inFirstLine line: String) -> String? {
    guard let object = jsonObject(line), object["type"] as? String == "session_meta",
      let payload = object["payload"] as? [String: Any],
      let cwd = payload["cwd"] as? String, !cwd.isEmpty
    else { return nil }
    return cwd
  }

  private static func jsonObject(_ line: String) -> [String: Any]? {
    guard let data = line.data(using: .utf8), !data.isEmpty else { return nil }
    return (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
  }

  // MARK: Building

  /// Which backends have a resumable conversation for each of `cwds`, as of `savedAt`.
  ///
  /// Blocking. The caller runs this off the main actor and delivers the result back on it; see
  /// `AgentResumeCoordinator`. `isCancelled` is consulted between entries so a scan whose panes have
  /// all closed stops promptly rather than finishing on principle.
  func backends(
    forCwds cwds: [String], savedAt: Date, isCancelled: @escaping () -> Bool = { false }
  ) -> [String: Set<AgentBackend>] {
    var budget = Budget(limits: limits, start: now(), now: now, isCancelled: isCancelled)
    var result: [String: Set<AgentBackend>] = [:]

    for cwd in cwds where !budget.isExhausted {
      if claudeHasHistory(cwd: cwd, savedAt: savedAt, budget: &budget) {
        result[cwd, default: []].insert(.claude)
      }
    }

    // Codex cannot be addressed by path — its tree is keyed by date — so the day directories are
    // scanned once and every pane is answered from the resulting set, rather than re-walking them
    // per pane.
    //
    // The lookup is a Set membership test, NOT a linear scan with `pathsMatch`. That distinction is
    // the difference between bounded and not: `pathsMatch` falls through to
    // `resolvingSymlinksInPath()` on every non-equal pair, so scanning a 2,000-entry set for each of
    // 40 restored panes would be 160,000 filesystem syscalls — on the launch path, *after* the
    // budget had already said stop, because this loop never consulted it. Indexing both the textual
    // and the resolved form up front pays the syscalls once per recorded cwd instead.
    if !budget.isExhausted {
      let codexCwds = codexRecordedCwds(savedAt: savedAt, budget: &budget)
      for cwd in cwds
      where codexCwds.contains(Self.trimmed(cwd)) || codexCwds.contains(Self.resolved(cwd)) {
        result[cwd, default: []].insert(.codex)
      }
    }

    if budget.isExhausted {
      Self.logger.notice(
        "agent session scan stopped early (files: \(budget.filesOpened, privacy: .public)) — offers may be incomplete"
      )
    }
    return result
  }

  private func claudeHasHistory(cwd: String, savedAt: Date, budget: inout Budget) -> Bool {
    // The hint first: one directory listing instead of 58.
    let hinted = roots.claudeProjects.appendingPathComponent(
      Self.claudeSlugHint(for: cwd), isDirectory: true)
    if directoryExists(hinted),
      transcriptMatches(in: hinted, cwd: cwd, savedAt: savedAt, budget: &budget)
    {
      return true
    }
    // The hint missed — an undocumented character class, or a genuinely absent directory. Fall back
    // to looking at every project directory, which is what makes the hint safe to be wrong about.
    guard !directoryExists(hinted) else { return false }
    for directory in enumerateClaudeProjects() where !budget.isExhausted {
      guard directory != hinted else { continue }
      if transcriptMatches(in: directory, cwd: cwd, savedAt: savedAt, budget: &budget) {
        return true
      }
    }
    return false
  }

  /// Depth 1 only. `~/.claude/projects/<slug>/` also holds per-session subdirectories and other
  /// tooling state; the resumable unit is a `.jsonl` sitting directly in the project directory.
  private func transcriptMatches(
    in directory: URL, cwd: String, savedAt: Date, budget: inout Budget
  ) -> Bool {
    for file in recentJSONLFiles(in: directory, savedAt: savedAt) where !budget.isExhausted {
      budget.filesOpened += 1
      let lines = head(of: file, lines: limits.maxLinesPerFile)
      guard let recorded = Self.claudeCwd(inLines: lines) else { continue }
      if Self.pathsMatch(recorded, cwd) { return true }
    }
    return false
  }

  private func enumerateClaudeProjects() -> [URL] {
    contents(of: roots.claudeProjects).filter { directoryExists($0) }
  }

  /// Every `cwd` recorded by a Codex rollout inside the recency window, indexed for O(1) lookup.
  ///
  /// Each recorded path is inserted BOTH textually and symlink-resolved, so the caller can answer
  /// "does this pane match?" with two Set probes instead of a linear scan that resolves symlinks per
  /// comparison. Resolution happens once per recorded cwd, not once per (pane, cwd) pair.
  private func codexRecordedCwds(savedAt: Date, budget: inout Budget) -> Set<String> {
    memoLock.lock()
    let memo = codexCwdMemo
    memoLock.unlock()
    if let memo { return memo }

    var found: Set<String> = []
    for day in codexDayDirectories(savedAt: savedAt) where !budget.isExhausted {
      for file in recentJSONLFiles(in: day, savedAt: savedAt, prefix: "rollout-")
      where !budget.isExhausted {
        budget.filesOpened += 1
        guard let first = head(of: file, lines: 1).first,
          let recorded = Self.codexCwd(inFirstLine: first)
        else { continue }
        found.insert(Self.trimmed(recorded))
        found.insert(Self.resolved(recorded))
      }
    }
    // Only memoize a COMPLETE walk. Caching a budget-truncated set would make the first window's
    // bad luck permanent for every window after it.
    if !budget.isExhausted {
      memoLock.lock()
      codexCwdMemo = found
      memoLock.unlock()
    }
    return found
  }

  /// Only the `YYYY/MM/DD` directories whose day intersects the window — at most three for a 12-hour
  /// window, however many years of sessions the store holds.
  private func codexDayDirectories(savedAt: Date) -> [URL] {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = .current
    let days = Set(
      [-Self.recencyWindow, 0, Self.recencyWindow].map {
        calendar.startOfDay(for: savedAt.addingTimeInterval($0))
      })

    let formatter = DateFormatter()
    formatter.calendar = calendar
    formatter.timeZone = calendar.timeZone
    formatter.dateFormat = "yyyy/MM/dd"

    return days.sorted().map {
      roots.codexSessions.appendingPathComponent(formatter.string(from: $0), isDirectory: true)
    }
    .filter { directoryExists($0) }
  }

  // MARK: Filesystem

  private func recentJSONLFiles(in directory: URL, savedAt: Date, prefix: String? = nil) -> [URL] {
    contents(of: directory, keys: [.contentModificationDateKey, .isRegularFileKey])
      .filter { url in
        guard url.pathExtension == "jsonl" else { return false }
        if let prefix, !url.lastPathComponent.hasPrefix(prefix) { return false }
        let values = try? url.resourceValues(forKeys: [
          .contentModificationDateKey, .isRegularFileKey,
        ])
        // Regular files only. A symlinked candidate is a path out of the store we were pointed at,
        // and following one would let anything that can write into an agent directory aim our reads
        // somewhere else entirely.
        guard values?.isRegularFile == true, let modified = values?.contentModificationDate else {
          return false
        }
        return Self.isRecent(modified, savedAt: savedAt)
      }
  }

  private func contents(of directory: URL, keys: [URLResourceKey] = []) -> [URL] {
    (try? fileManager.contentsOfDirectory(
      at: directory, includingPropertiesForKeys: keys,
      options: [.skipsHiddenFiles, .skipsSubdirectoryDescendants])) ?? []
  }

  private func directoryExists(_ url: URL) -> Bool {
    var isDirectory: ObjCBool = false
    return fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory)
      && isDirectory.boolValue
  }

  /// The first `lines` lines of a file, reading at most `maxBytesPerFile`.
  ///
  /// A transcript grows without bound, so this never loads one whole: it pulls a bounded prefix and
  /// splits it. A trailing partial line is dropped unless it is the only thing read, which keeps a
  /// half-written record from being parsed as a complete one.
  private func head(of url: URL, lines: Int) -> [String] {
    guard let handle = try? FileHandle(forReadingFrom: url) else { return [] }
    defer { try? handle.close() }
    guard let data = try? handle.read(upToCount: limits.maxBytesPerFile), !data.isEmpty else {
      return []
    }
    // Whether the last line is complete is decided on the RAW BYTES, before decoding. Two bugs live
    // here otherwise: a capped read that happens to end exactly on a newline had its last (complete)
    // record thrown away, and a capped read with only one line kept a truncated one. Checking for a
    // trailing LF answers both, and slicing at the last LF keeps a multi-byte scalar cut by the cap
    // from decoding as a replacement character inside a line we actually parse.
    let cappedAndUnterminated = data.count == limits.maxBytesPerFile && data.last != 0x0A
    let usable =
      cappedAndUnterminated ? data[..<(data.lastIndex(of: 0x0A).map { $0 + 1 } ?? 0)] : data[...]
    guard !usable.isEmpty else { return [] }
    let text = String(decoding: usable, as: UTF8.self)
    let split = text.split(separator: "\n", omittingEmptySubsequences: true).map(String.init)
    return Array(split.prefix(lines))
  }

  // MARK: Budget

  /// The running cost of one build, so every limit is checked in one place rather than at each
  /// call site (where the next one added would be the one that gets forgotten).
  private struct Budget {
    let limits: Limits
    let start: Date
    let now: () -> Date
    let isCancelled: () -> Bool
    var filesOpened = 0

    var isExhausted: Bool {
      isCancelled() || filesOpened >= limits.maxFiles
        || now().timeIntervalSince(start) >= limits.deadline
    }
  }
}

  /// Copy (write) — ⌘C and OSC 52 writes. Writes the first text payload to the general pasteboard.
  nonisolated func writeClipboard(
    userdata: UnsafeMutableRawPointer?,
    location: ghostty_clipboard_e,
    content: UnsafePointer<ghostty_clipboard_content_s>?,
    count: Int,
    confirm: Bool
  ) {
    guard let content, count > 0 else { return }
    var text: String?
    for i in 0..<count {
      let entry = content[i]
      // Only forward text payloads: a binary mime (image/*, etc.) would be garbled by
      // String(cString:), and breaking on the first non-null entry would skip a later text/plain one.
      let isText = entry.mime.map { String(cString: $0).hasPrefix("text/") } ?? true
      guard isText, let data = entry.data else { continue }
      text = String(cString: data)
      break
    }
    guard let text, !text.isEmpty else { return }
    let pb = NSPasteboard.general
    pb.clearContents()
    pb.setString(text, forType: .string)
  }

  /// Paste (read) — ⌘V and OSC 52 reads. Completes the request with the pasteboard's text.
  nonisolated func readClipboard(
    userdata: UnsafeMutableRawPointer?,
    location: ghostty_clipboard_e,
    state: UnsafeMutableRawPointer?
  ) -> Bool {
    guard let userdata else { return false }
    let view = Unmanaged<GhosttySurfaceView>.fromOpaque(userdata).takeUnretainedValue()
    guard let surface = view.surface else { return false }
    let text = NSPasteboard.general.string(forType: .string) ?? ""
    // ⌘V never reaches `insertText` — libghostty owns the keybind and completes the read straight
    // into the surface — so the pane has to be marked dirty here or issue #145's resume action would
    // append a Return to whatever was just pasted and run it.
    if !text.isEmpty { view.noteUserInput() }
    text.withCString { ghostty_surface_complete_clipboard_request(surface, $0, state, false) }
    return true
  }

  nonisolated func confirmReadClipboard(
    userdata: UnsafeMutableRawPointer?,
    content: UnsafePointer<CChar>?,
    state: UnsafeMutableRawPointer?,
    request: ghostty_clipboard_request_e
  ) {
    // OSC 52 read confirmation flow is not surfaced to the user in Workroom; nothing to confirm.
  }

  // MARK: Close

  nonisolated func closeSurface(userdata: UnsafeMutableRawPointer?, needsConfirm: Bool) {
    // Workroom owns its tab lifecycle (plan A5): a surface/shell exiting leaves the tab in place (as
    // SwiftTerm did) until the user closes it, so libghostty's close request is intentionally ignored.
  }

  // MARK: Notification mapping (T2 — pure, unit-tested)

  /// Map a libghostty desktop-notification (title, optional body) to Workroom's `TerminalActivity`.
  /// Pure + side-effect-free so it's testable without a live terminal (replaces the deleted
  /// `OSCParserTests` coverage). The title is kept verbatim — including empty: the UI shows no
  /// placeholder for a titleless notification (it leads with the body instead). Empty body → nil.
  static func terminalActivity(title: String, body: String?) -> TerminalActivity {
    let resolvedBody = (body?.isEmpty ?? true) ? nil : body
    return .osc(title: title, body: resolvedBody)
  }
}

/// surface is created (i.e. before the view enters a window), which is where
/// `TerminalSessions.restore` sets it — immediately after the factory returns.
///
/// The closure is called at most once, when the surface is created, and released straight after —
/// so a restored pane that is never opened costs a closure, not a copy of its history.
func adoptRestoredScrollback(_ provider: (() -> String?)?) {
  guard surface == nil, let provider else { return }
  restoredScrollback = provider
}

/// Type literal text into the surface WITHOUT a trailing newline ("Insert fix", issue #49): the
/// user reviews and presses Return themselves — we never auto-execute an AI-suggested command.
///
/// **Marks the pane dirty** (issue #145). Inserted text sits unsubmitted on the input line, which
/// is exactly the state a resume offer must not append a Return to.
func sendText(_ string: String) {
  guard !string.isEmpty else { return }
  noteUserInput()
  writeText(string)
}

/// Put text on the PTY with no side effects. The raw primitive behind `sendText` and
/// `sendCommandLine`, split out so those two can differ on whether the pane becomes dirty.
private func writeText(_ string: String) {
  guard let surface, !string.isEmpty else { return }
  string.withCString { ghostty_surface_text(surface, $0, UInt(string.utf8.count)) }
}

/// Type a command into the surface **and run it** (issue #145's Resume action).
///
/// A separate entry point rather than a `submit:` flag on `sendText`, so that method's guarantee
/// stays exactly as narrow and as greppable as it was: an AI-*suggested* command is never
/// auto-executed. The distinction is the provenance, not the mechanism. `sendText` carries a string
/// a model produced, which nobody has read yet. This carries a compile-time constant
/// (`AgentInvocationBuilder.resume`) behind a button labelled Resume — the click is the review.
///
/// Callers must confirm the pane is pristine first (`AgentResumeCoordinator.paneReceivedInput`),
/// since appending to a half-typed line would run something else entirely.
///
/// **Return goes through the KEY path, not the text path — measured, not assumed.** Appending
/// `"\r"` to `ghostty_surface_text` does not submit: the engine drops the control byte, and
/// `AgentResumeUITests` caught it with the command sitting on the prompt, typed and never run:
///
/// ```
///   ❯ claude --resume
/// ```
///
/// `ghostty_surface_text` is the *text input* path (it also backs `NSTextInputClient.insertText`),
/// so a control byte there is not a keystroke. Return has to arrive as one.
/// Writes through `writeText`, NOT `sendText`: this is the one caller that must not mark the pane
/// dirty, because the offer it is spending has already been consumed.
func sendCommandLine(_ commandLine: String) {
  guard surface != nil, !commandLine.isEmpty else { return }
  writeText(commandLine)
  sendReturn()
}

/// Press Return, exactly as `keyDown` would forward it.
///
/// `keycode` is the **native macOS virtual keycode** — libghostty does the mapping — so this is
/// `kVK_Return`, not `GHOSTTY_KEY_ENTER`. Only the press is sent, matching `keyDown`, which never
/// forwards a release either.
private func sendReturn() {
  guard let surface else { return }
  var keyEvent = ghostty_input_key_s()
  keyEvent.action = GHOSTTY_ACTION_PRESS
  keyEvent.keycode = 0x24  // kVK_Return
  keyEvent.mods = GHOSTTY_MODS_NONE
  keyEvent.consumed_mods = GHOSTTY_MODS_NONE
  keyEvent.composing = false
  keyEvent.text = nil
  keyEvent.unshifted_codepoint = 0x0D
  _ = ghostty_surface_key(surface, keyEvent)
}

/// **Fixture-only.** Expose the visible screen text to the accessibility tree so an XCUITest can
/// assert what a terminal actually did.
///
/// A libghostty surface renders through Metal, so its contents are invisible to XCUITest — which
/// leaves whole behaviours unassertable end to end. The one that forced this: issue #145 types a
/// command in and submits it with `\r`, and if a libghostty version ever filtered control bytes out
/// of the text path the command would be typed and never run. That failure is silent from the
/// outside and there is no unit test for it, because the behaviour under test belongs to the engine.
///
/// Gated on `UITestFixture.isActive`, which is itself `#if DEBUG` — a release build reads nothing
/// and publishes nothing. `VIEWPORT` is the visible screen only, never the scrollback.
override func isAccessibilityElement() -> Bool {
  UITestFixture.isActive ? true : super.isAccessibilityElement()
}

override func accessibilityValue() -> Any? {
  guard UITestFixture.isActive else { return super.accessibilityValue() }
  return readText(tag: GHOSTTY_POINT_VIEWPORT) ?? ""
}

override func accessibilityIdentifier() -> String {
  UITestFixture.isActive ? "terminal.surface" : super.accessibilityIdentifier()
}

